package ru.truetv.launcher;
import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.os.*;
import android.provider.DocumentsContract;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

/** Fresh-install desktop, Home lifecycle and embedded helper; own disposable VM only. */
public final class LauncherFixCheck extends Instrumentation {
 private Context c;private int checks;private final StringBuilder out=new StringBuilder();private HomeActivity home;private FileActivity files;private AccessActivity access;private File fixture;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String why){out.append(ok?"PASS ":"FAIL ").append(why).append('\n');checks++;if(!ok)throw new AssertionError(why);}
 private void main(Runnable run){Throwable[] error={null};runOnMainSync(()->{try{run.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new AssertionError(error[0]);}
 private Object field(Object object,String name){try{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(Exception e){throw new AssertionError(e);}}
 private void call(Object object,String name,Class<?> type,Object arg){try{Method m=type==null?object.getClass().getDeclaredMethod(name):object.getClass().getDeclaredMethod(name,type);m.setAccessible(true);if(type==null)m.invoke(object);else m.invoke(object,arg);}catch(Exception e){throw new AssertionError(e);}}
 private String shell(String command)throws Exception {try(ParcelFileDescriptor p=getUiAutomation().executeShellCommand(command);InputStream in=new FileInputStream(p.getFileDescriptor());ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);return new String(bytes.toByteArray(),"UTF-8");}}
 private void shot(String name)throws Exception {VmWindows.ready(this);Thread.sleep(250);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 private void waitTile(int slot,String pkg)throws Exception {long end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end){waitForIdleSync();if(home.board.getChildCount()>slot&&((Tile)home.board.getChildAt(slot)).pkg.equals(pkg))return;Thread.sleep(80);}throw new AssertionError("Tile not updated: "+pkg);}
 private void pick(int slot,String pkg)throws Exception {ActivityMonitor monitor=new ActivityMonitor(CatalogActivity.class.getName(),null,false);addMonitor(monitor);main(()->home.board.getChildAt(slot).performClick());CatalogActivity picker=(CatalogActivity)waitForMonitorWithTimeout(monitor,15000);removeMonitor(monitor);check(picker!=null,"plus opens catalog Activity for slot "+slot);VmWindows.ready(this);GridView grid=picker.grid;int index=-1;for(int i=0;i<grid.getAdapter().getCount();i++)if(((AppCatalog.Entry)grid.getAdapter().getItem(i)).pkg.equals(pkg)){index=i;break;}check(index>=0,"catalog includes "+pkg);final int at=index;main(()->grid.performItemClick(grid.getAdapter().getView(at,null,grid),at,at));waitTile(slot,pkg);check(new SettingsStore(c).slot(slot).equals(pkg),"picked package stored in exact slot "+slot);check(picker.isFinishing(),"confirmed save closes catalog Activity");long end=SystemClock.uptimeMillis()+5000;while(!home.board.getChildAt(slot).hasFocus()&&SystemClock.uptimeMillis()<end){waitForIdleSync();Thread.sleep(80);}check(home.board.getChildAt(slot).hasFocus(),"focus returns to added tile "+slot);}
 @SuppressWarnings("unchecked")public void onStart(){c=getTargetContext();Bundle done=new Bundle();try{
  check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("Android SDK"),"disposable VM guard");VmWindows.prepare(this);new SettingsStore(c).data.edit().clear().putBoolean("bt_asked",true).putBoolean("bt_count",false).commit();AppCatalog app=AppCatalog.get(c);long end=SystemClock.uptimeMillis()+20000;while(!app.loaded()&&SystemClock.uptimeMillis()<end)Thread.sleep(80);check(app.loaded(),"catalog loaded on fresh install");
  home=VmWindows.home(this);waitForIdleSync();check(app.find("ru.truetv.probe").launch!=null,"fixture with launcher activity");check(app.find("ru.truetv.launcher.tests").launch==null,"fixture without launcher activity");pick(0,"ru.truetv.probe");pick(1,"ru.truetv.launcher.tests");
  main(home::finish);home=VmWindows.home(this);waitTile(0,"ru.truetv.probe");waitTile(1,"ru.truetv.launcher.tests");check(home.visiblePackages().contains("ru.truetv.launcher.tests"),"assignments restored in new Home instance");
  ActivityMonitor resumeMonitor=new ActivityMonitor(SettingsActivity.class.getName(),null,false);addMonitor(resumeMonitor);main(()->home.header.getChildAt(3).performClick());SettingsActivity pausedBy=(SettingsActivity)waitForMonitorWithTimeout(resumeMonitor,12000);removeMonitor(resumeMonitor);check(pausedBy!=null,"real settings Activity pauses Home before restored assignment");Thread save=new Thread(()->new SettingsStore(c).assignSaved(2,"ru.truetv.probe"));save.start();save.join();main(pausedBy::finish);waitTile(2,"ru.truetv.probe");check(((Tile)home.board.getChildAt(2)).pkg.equals("ru.truetv.probe"),"onResume reads saved assignment without Activity result");
  String own=c.getPackageName()+"/ru.truetv.launcher.HomeActivity";shell(Build.VERSION.SDK_INT>=29?"cmd role add-role-holder --user 0 android.app.role.HOME ru.truetv.launcher 1":"cmd package set-home-activity "+own);check(HomeDefaults.isOwn(shell(HomeDefaults.query(0))),"test-only Home default assigned on disposable VM");Board before=home.board;View focused=home.board.getChildAt(1);main(focused::requestFocusFromTouch);
  for(int i=0;i<3;i++){shell("input keyevent 3");waitForIdleSync();check(home.board==before&&!home.isFinishing(),"single Home keeps existing board "+i);}
  shell("input keyevent 3 3");waitForIdleSync();check(home.board==before,"rapid double Home does not rebuild board");check(shell("cmd package resolve-activity --brief -a android.intent.action.MAIN -c android.intent.category.HOME").contains("ru.truetv.launcher"),"repeated Home preserves system default");check(home.visiblePackages().size()==3,"repeated Home keeps desktop assignments");shot("home219-final.png");
  ActivityMonitor monitor=new ActivityMonitor(AccessActivity.class.getName(),null,false);addMonitor(monitor);main(()->Controls.restricted(home));access=(AccessActivity)waitForMonitorWithTimeout(monitor,15000);removeMonitor(monitor);check(access!=null&&access.getPackageName().equals(c.getPackageName()),"restricted entry opens embedded TV Access without external helper");end=SystemClock.uptimeMillis()+15000;ListView services=(ListView)field(access,"list");while(services.getAdapter().getCount()==0&&SystemClock.uptimeMillis()<end)Thread.sleep(80);check(services.getAdapter().getCount()>0,"embedded service list loaded");Set<String> eligible=AccessActivity.packages(c);check(eligible.contains(c.getPackageName())&&eligible.contains("ru.truetv.probe"),"only apps declaring bound Accessibility services are eligible");check(((Set<?>)field(access,"selected")).isEmpty(),"opening helper does not preselect or grant apps");main(()->services.performItemClick(services.getAdapter().getView(0,null,services),0,0));check(((Set<?>)field(access,"selected")).size()==1,"remote selection toggles one package");check(((TextView)field(access,"state")).getText().toString().contains("127.0.0.1:5555"),"ADB address visible in own helper");shot("access219-final.png");main(access::finish);access=null;waitForIdleSync();check(home.board==before&&home.visiblePackages().size()==3,"return from unchanged helper preserves the existing desktop");
  fixture=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"TrueTV219-"+System.currentTimeMillis());check(fixture.mkdir(),"own file fixture");new File(fixture,"folder").mkdir();try(FileOutputStream write=new FileOutputStream(new File(fixture,"file.txt"))){write.write(1);}files=(FileActivity)startActivitySync(new Intent(c,FileActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra(DocumentsContract.EXTRA_INITIAL_URI,FileStore.get(c).uri(FileStore.get(c).identify(fixture))));end=SystemClock.uptimeMillis()+15000;while(((List<?>)field(files,"entries")).size()!=2&&SystemClock.uptimeMillis()<end)Thread.sleep(80);waitForIdleSync();TextView count=(TextView)field(files,"selectedCount");check(count.getVisibility()==View.GONE&&count.getText().length()==0,"zero-selection counter is hidden and reserves no width");FileStore.Node n=((List<FileStore.Node>)field(files,"entries")).get(0);main(()->call(files,"toggle",FileStore.Node.class,n));check(count.getVisibility()==View.VISIBLE&&count.getText().toString().contains("1/2"),"counter appears after actual selection");main(files::onBackPressed);check(count.getVisibility()==View.GONE&&!files.isFinishing(),"Back clears selection and hides counter without leaving files");shot("files219-final.png");
  Configuration original=new Configuration(files.getResources().getConfiguration());try{Configuration ru=new Configuration(original);ru.setLocale(new Locale("ru"));main(()->{files.getResources().updateConfiguration(ru,files.getResources().getDisplayMetrics());call(files,"refreshFolderActions",null,null);});Thread.sleep(150);waitForIdleSync();Button sort=(Button)((LinearLayout)field(files,"folderActions")).getChildAt(6);check(sort.getText().toString().startsWith("Порядок\n"),"short Russian sorting caption");check(sort.getLayout()!=null&&sort.getText().subSequence(0,sort.getLayout().getLineEnd(0)).toString().trim().equals("Порядок"),"entire Russian caption stays on first line");}finally{main(()->{files.getResources().updateConfiguration(original,files.getResources().getDisplayMetrics());call(files,"refreshFolderActions",null,null);});}
  done.putBoolean("passed",true);done.putString("report",out+"Checks="+checks);
 }catch(Throwable error){StringWriter trace=new StringWriter();error.printStackTrace(new PrintWriter(trace));done.putBoolean("passed",false);done.putString("report",out+trace.toString());}finally{try{if(files!=null)main(files::finish);if(access!=null)main(access::finish);if(home!=null)main(home::finish);if(fixture!=null)FileCore.erase(fixture,FileCore.NEVER);shell(Build.VERSION.SDK_INT>=29?"cmd role add-role-holder --user 0 android.app.role.HOME com.android.launcher3 1":"cmd package set-home-activity com.android.launcher3/.Launcher");}catch(Exception ignored){}}finish(done.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,done);}
}
